// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        address owner = address(this);
        c.mintToken(owner, 1);
        c.burn(1);
        bool success;
        try c.owned() {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == true, "owned() should not revert");
    }
}
